use axum::body::{to_bytes, Body};
use axum::http::{Request, StatusCode};
use axum::Router;
use tower::ServiceExt;

// Provided: sends a request to the router without a network and returns (status, body)
async fn call(app: &Router, method: &str, uri: &str, body: &str) -> (StatusCode, String) {
    let req = Request::builder()
        .method(method)
        .uri(uri)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .unwrap();
    let res = app.clone().oneshot(req).await.unwrap();
    let status = res.status();
    let bytes = to_bytes(res.into_body(), 1 << 20).await.unwrap();
    (status, String::from_utf8_lossy(&bytes).into_owned())
}

fn app() -> Router {
    Router::new()
}

#[tokio::main]
async fn main() {
    let app = app();
    println!("{:?}", call(&app, "GET", "/", "").await);
    println!("{:?}", call(&app, "GET", "/nope", "").await);
}

